function check([nums, threshold], actual, expected) {
  if (expected === -1) return actual === -1;
  if (!Number.isInteger(actual) || actual < 1 || actual > nums.length) return false;
  // Look for a run of at least actual elements that each beat threshold / actual.
  let run = 0;
  for (const value of nums) {
    run = value * actual > threshold ? run + 1 : 0;
    if (run >= actual) return true;
  }
  return false;
}

