function validate([nums, threshold]) {
  if (nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1e9)) return 'Each value of nums is an integer from 1 to 10^9.';
  if (!Number.isInteger(threshold) || threshold < 1 || threshold > 1e9) return 'threshold is an integer from 1 to 10^9.';
  return null;
}

