function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(1, 8), top = pick(1, 12);
    const nums = Array.from({ length: n }, () => pick(1, top));
    return [nums, pick(1, top * n + 2)];
  }
  const n = 2000, mode = pick(0, 2);
  if (mode === 0) return [Array.from({ length: n }, () => pick(1, 1e9)), pick(1, 1e9)];
  if (mode === 1) return [Array.from({ length: n }, () => pick(1, 1000)), pick(1000, 200000)];
  // A hill: the middle is high and the sides are low, so the best block is a wide middle window.
  const step = pick(1, 1000);
  return [Array.from({ length: n }, (_, i) => 1 + Math.min(i, n - 1 - i) * step), pick(1e8, 1e9)];
}
